import type { ReactNode } from "react";
import { Montserrat, Syne } from "next/font/google";
import "./globals.css";

const syne = Syne({
  subsets: ["latin"],
  variable: "--font-display",
  display: "swap",
});

const montserrat = Montserrat({
  subsets: ["latin"],
  variable: "--font-body",
  display: "swap",
});

export const metadata = {
  title: "hrmny OS — Build desk",
  description: "Team desk + client portal for Creative Harmony",
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en" className={`${syne.variable} ${montserrat.variable}`}>
      <body>
        <div className="grain" aria-hidden />
        {children}
      </body>
    </html>
  );
}

:root {
  --ochre: #e47300;
  --ink: #0a0908;
  --paper: #f7f4ef;
  --sand: #e8e0d4;
  --muted: #6b6560;
  --glass: rgba(255, 255, 255, 0.55);
  --glass-border: rgba(10, 9, 8, 0.08);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  color: var(--ink);
  background: var(--paper);
}

body {
  font-family: var(--font-body), system-ui, sans-serif;
  background:
    radial-gradient(1200px 600px at 10% -10%, rgba(228, 115, 0, 0.18), transparent 55%),
    radial-gradient(900px 500px at 90% 0%, rgba(10, 9, 8, 0.08), transparent 50%),
    linear-gradient(180deg, #faf7f2 0%, #efe8dc 48%, #e7dfd2 100%);
}

a {
  color: inherit;
  text-decoration: none;
}

.scene {
  perspective: 1400px;
  transform-style: preserve-3d;
}

.panel-3d {
  transform: rotateX(8deg) rotateY(-6deg);
  transform-style: preserve-3d;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: transform;
}

.panel-3d:hover {
  transform: rotateX(2deg) rotateY(-2deg) translateZ(12px);
}

.panel-3d.float {
  animation: float3d 7s ease-in-out infinite;
}

@keyframes float3d {
  0%,
  100% {
    transform: rotateX(8deg) rotateY(-6deg) translateY(0);
  }
  50% {
    transform: rotateX(8deg) rotateY(-6deg) translateY(-10px);
  }
}

.pulse-bar {
  animation: pulseBar 2.4s ease-in-out infinite;
}

@keyframes pulseBar {
  0%,
  100% {
    opacity: 0.85;
  }
  50% {
    opacity: 1;
  }
}

.grain {
  pointer-events: none;
  position: fixed;
  inset: 0;
  opacity: 0.04;
  z-index: 50;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

import Link from "next/link";
import type { CSSProperties } from "react";
import { M1_ITEMS, MILESTONES, m1Score } from "@/lib/m1-status";

const STATE_STYLE: Record<string, { bg: string; label: string }> = {
  done: { bg: "#d8f3e3", label: "Done" },
  partial: { bg: "#ffe6c2", label: "Partial" },
  blocked: { bg: "#ffd0cb", label: "Blocked" },
  todo: { bg: "#e8e0d4", label: "Todo" },
};

export default function TeamDeskPage() {
  const m1 = m1Score();

  return (
