            <div style={{ display: "flex", gap: 12, marginTop: 28, flexWrap: "wrap" }}>
              <a href="#m1" style={primaryBtn}>
                Open M1 checklist
              </a>
              <Link href="/portal" style={ghostBtn}>
                Preview portal
              </Link>
            </div>
          </div>

          <div className="scene" style={{ display: "flex", alignItems: "center" }}>
            <div
