              fontFamily: "var(--font-display)",
              fontSize: 28,
              letterSpacing: "-0.03em",
            }}
          >
            Where we go next
          </h2>
          <ol
            style={{
              margin: "16px 0 0",
              paddingLeft: 20,
              color: "var(--ink)",
              lineHeight: 1.8,
              maxWidth: 640,
